import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.StreamTokenizer

fun cube(x: Int): Long {
    return x.toLong() * x.toLong() * x.toLong()
}

fun foo(n: Long): Long {
    var ans = 0L
    var k = 2
    while (true) {
        val x = n / cube(k)
        if (x == 0L) {
            break
        }
        ans += x
        k++
    }
    return ans
}

// najmniejszy argument, dla ktorego f(arg) zwraca prawde
// funkcja logiczna powinna byc niemalejaca
fun binSearch(f: (Long) -> Boolean, lo0: Long, up0: Long, eps: Long): Long {
    var lo = lo0
    var up = up0
    up++
    var cnt = up - lo
    var mid: Long
    var step: Long
    while (cnt >= eps) {
        step = cnt / 2
        mid = lo + step
        if (!f(mid)) {
            lo = mid + eps
            cnt -= step + eps
        } else {
            cnt = step
        }
    }
    return lo
}

