    val m = getInt64()
    val mx = 4949100894494448L
    val x = { n: Long -> foo(n) >= m }

    var p = binSearch(x, 1, mx, 1)

    if (foo(p) != m) {
        p = -1
    }

    println(p)
}

class Input(stream: java.io.InputStream) {
