typealias FLess = (Int, Int) -> Boolean
typealias FSwap = (Int, Int) -> Unit

class WrapSort(val length: Int, val fless: FLess, val fswap: FSwap) {
    fun len(): Int = length
    fun less(i: Int, j: Int): Boolean = fless(i, j)
    fun swap(i: Int, j: Int) = fswap(i, j)
}

fun wsort(length: Int, fless: FLess, fswap: FSwap) {
    val w = WrapSort(length, fless, fswap)
    for (i in 1 until w.len()) {
        var j = i
        while (j > 0 && w.less(j, j - 1)) {
            w.swap(j, j - 1)
            j--
        }
    }
}
